<template><view class="page"><MeetingContentHeader title="会议导航" :activity-id="activityId" /><view v-if="loading" class="state">加载中...</view><view v-else class="list"><view v-for="item in rows" :key="item.navId" class="card" @click="navigate(item)"><image v-if="item.coverUrl" :src="item.coverUrl" mode="aspectFill" /><view class="body"><view class="title">{{ item.title }}</view><view class="sub">{{ item.address }}</view><view v-if="item.phone" class="sub">{{ item.phone }}</view></view><text v-if="item.canNavigate" class="go">导航</text></view><view v-if="!rows.length" class="state">暂无导航点</view></view></view></template>
<script setup>import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import MeetingContentHeader from '@/components/MeetingContentHeader.vue';import{getPortalNavigation}from '@/api/portal/meeting';const activityId=ref(''),rows=ref([]),loading=ref(true);function navigate(item){if(!item.canNavigate)return;uni.openLocation({latitude:Number(item.latitude),longitude:Number(item.longitude),name:item.title,address:item.address||''})}onLoad(o=>{activityId.value=o?.activityId||'';getPortalNavigation(activityId.value).then(r=>rows.value=r.data||[]).finally(()=>loading.value=false)});</script><style scoped>.page{min-height:100vh;background:#f5f7fa}.list{padding:110rpx 24rpx 24rpx}.card{display:flex;align-items:center;gap:18rpx;padding:20rpx;margin-bottom:18rpx;background:#fff;border-radius:16rpx}.card image{width:100rpx;height:100rpx;border-radius:12rpx}.body{flex:1}.title{font-weight:600}.sub{margin-top:8rpx;color:#909399;font-size:24rpx}.go{color:#409eff;font-size:24rpx}.state{padding:180rpx 24rpx;text-align:center;color:#909399}</style>
